import type { EliteaModel, ModelCatalog } from "../elitea.js";

export interface LaunchContext {
  /** Resolved path of the agent executable. */
  bin: string;
  /** EliteA base URL, e.g. https://next.elitea.ai */
  url: string;
  token: string;
  projectId: number;
  catalog: ModelCatalog;
  model: EliteaModel;
  fastModel: EliteaModel;
  /** Args after `--`, passed through to the agent unchanged. */
  extraArgs: string[];
  /** For the session context text; from the saved login. */
  userName?: string;
  projectName?: string;
  /** Generated by launch (claudePlugin.ts): elitea-cli shim dir + Claude Code plugin dir. */
  tools?: { shimDir: string; pluginDir: string };
}

export interface LaunchSpec {
  args: string[];
  /** Merged over process.env; an empty string means "set to empty", undefined means "unset". */
  env: Record<string, string | undefined>;
}

export interface Integration {
  name: string;
  aliases: string[];
  displayName: string;
  /** Which model family the agent is built around; drives default model choice. */
  family: "anthropic" | "openai";
  /** Whether the agent uses a separate small model (Claude Code's haiku slot). */
  usesFastModel: boolean;
  /** Executable name plus well-known install locations outside PATH. */
  binary: { name: string; fallbacks: string[] };
  installHint: string;
  prepare(ctx: LaunchContext): Promise<LaunchSpec>;
}
